package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var curRec LedgerRec
var ledgerFile *os.File
var reader *bufio.Reader

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func formatAmtEd(d decimal.Decimal) string {
	// PIC ZZ,ZZ9.99  width 9
	return formatEdited(d, 6, []int{3}, 2, false)
}

func formatBalEd(d decimal.Decimal) string {
	// PIC -Z,ZZZ,ZZ9.99 width 13, sign leading
	return formatEdited(d, 7, []int{4, 1}, 2, true)
}
func formatTotEd(d decimal.Decimal) string {
	// PIC -ZZZ,ZZZ,ZZ9.99 width 15
	return formatEdited(d, 9, []int{6, 3}, 2, true)
}

// formatEdited formats decimal d according to COBOL numeric-edited rules.
// intDigits = number of Z+9 before decimal
// commaPos = positions from right where commas would be (integer digit index)
// scale = fractional digits (after decimal)
// signed = first char is sign: '-' if negative else ' '
// total width is: (signed?1:0) + intDigits + len(commaPos) + (scale>0?1+scale:0)
func formatEdited(d decimal.Decimal, intDigits int, commaPos []int, scale int, signed bool) string {
	neg := d.IsNegative()
	abs := d.Abs()
	// truncate to scale toward zero (MOVE does truncation)
	abs = abs.Truncate(int32(scale))

	// integer part
	intPart := abs.IntPart() // truncates fractional
	// overflow: keep low-order digits
	mod := int64(1)
	for i := 0; i < intDigits; i++ {
		mod *= 10
	}
	intPart = intPart % mod

	// fractional part: scale digits
	// compute fractional integer 0..10^scale-1
	// fractional = (abs - intPartTruncated)*10^scale truncated
	tenScale := decimal.New(1, int32(scale))
	fracDec := abs.Mul(tenScale).Truncate(0)
	// fractional = fracDec % 10^scale
	fracInt := fracDec.IntPart() % tenScale.IntPart()
	if fracInt < 0 {
		fracInt = -fracInt
	}

	// Build integer digit chars array length intDigits
	digits := make([]byte, intDigits)
	tmp := intPart
	for i := intDigits - 1; i >= 0; i-- {
		digits[i] = byte('0' + tmp%10)
		tmp /= 10
	}

	// Determine suppression: leading zeros replaced by spaces
	// Suppression continues up to the last '9' position (which is the rightmost digit)
	// In our pictures, the last position is always 9, so all but last digit are Z.
	// General rule: leading Z's become spaces until first non-zero.
	// We can implement by finding first non-zero digit index; all Z positions before it become spaces.
	// But we need to know which positions are Z vs 9. For these pictures, only last is 9, rest Z.
	// So suppress up to intDigits-1.
	numNine := 1 // last digit is 9
	firstNonZero := -1
	for i, ch := range digits {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	// Build integer field with commas
	// int field length = intDigits + len(commaPos)
	// Comma positions: counting from right (0-indexed) between digits
	// e.g., for 6 digits ZZ,ZZ9 -> comma after 3 digits from left? Actually picture ZZ,ZZ9 => groups: 2,2,1? But with leading spaces commas suppressed.
	// Simpler: define comma after k digits from left. For 6 digits with comma at 3 from right? 6 digits: positions: d0 d1 , d2 d3 d4? Wait.
	// Let's define commaPos as digit index from right where comma follows.
	// For ZZ,ZZ9.99 with intDigits=6: picture is Z Z , Z Z 9 => comma between index 1 and 2 (from left) i.e., 4 from right? Need to map.
	// Actually easier: picture strings given: "ZZ,ZZ9" => characters: Z Z , Z Z 9 => commas at picture pos 2.
	// The integer digits interleaved.
	// For intDigits=6, field with commas: indexes:
	// int char idx -> digit idx
	// 0:Z -> d0
	// 1:Z -> d1
	// 2:, -> comma
	// 3:Z -> d2
	// 4:Z -> d3
	// 5:9 -> d4? Wait mismatch.
	// Let's brute define by constructing picture template.
	// Instead use generic: we have comma insertion points defined as after certain number of digits from right.
	// For 6 digits, picture ZZ,ZZ9 => grouping 3,2? No.
	// Check expected: ZZ,ZZ9 represents up to 5? Actually counting: Z Z , Z Z 9 => that's 5 digit placeholders + comma = 6 chars for integer part. But we said intDigits=6, but picture shows 5 placeholders. Hmm confusion.
	// Let's recount: "ZZ,ZZ9.99" => before dot: "ZZ,ZZ9" => placeholders Z Z Z Z 9 = 5? No there are 4 Z +1 9 =5. Plus comma =6 chars integer part. Plus ".99"=3 => total 9. Yes intDigits=5 not 6. Wait earlier we counted 6.
	// Let's count again: ZZ,ZZ9 => chars: Z(1) Z(2) ,(3) Z(4) Z(5) 9(6) => digit count =5. So intDigits should be 5.
	// Similarly -Z,ZZZ,ZZ9 => Z ZZZ ZZ9 => 1+3+3=7 digit placeholders correct.
	// -ZZZ,ZZZ,ZZ9 => 9 digit placeholders correct.
	// So correct intDigits for Amt is 5.

	// To avoid confusion, set intDigits based on actual picture: we'll call with correct values.
	// Let's adjust caller: Amt should be 5.
	// But we passed 6 earlier. Need to correct below via detection: if len mismatch we fallback.
	// We'll handle generally: we have intDigits and comma count, total int field = intDigits + commaCount.
	// For Amt: intDigits=5, commaPos should be after 3? For picture ZZ,ZZ9 -> comma at 2 from left? Means 3 digits remain to right after comma. So comma distance from right =3.
	// For Bal: -Z,ZZZ,ZZ9 -> commas at distances 3 and 6 from right.
	// So we can define commaPos as distances from right.

	suppressed := make([]bool, intDigits)
	if firstNonZero == -1 {
		// all zeros: all Z become spaces, only last 9 prints 0
		for i := 0; i < intDigits-1; i++ {
			suppressed[i] = true
		}
	} else {
		for i := 0; i < firstNonZero; i++ {
			// if this position is Z (all except last numNine), suppress
			if i < intDigits-numNine {
				suppressed[i] = true
			}
		}
		// also if firstNonZero is within Z area, not suppressed; earlier zeros suppressed
	}

	// Build string
	var sb strings.Builder
	if signed {
		if neg {
			sb.WriteByte('-')
		} else {
			sb.WriteByte(' ')
		}
	}
	// integer part with commas
	// We iterate digit index from 0 to intDigits-1, and after each digit (except last) check if comma needed
	for i := 0; i < intDigits; i++ {
		var ch byte
		if suppressed[i] {
			ch = ' '
		} else {
			ch = digits[i]
		}
		sb.WriteByte(ch)
		if i != intDigits-1 {
			remaining := intDigits - 1 - i
			needComma := false
			for _, cp := range commaPos {
				if remaining == cp {
					needComma = true
					break
				}
			}
			if needComma {
				// if the whole leading zone up to here is suppressed, comma becomes space
				// COBOL: commas inside suppressed zone become spaces
				// Check if all digits up to and including next? Simpler: if all digits to left are suppressed and current also suppressed? We'll approximate: if the prefix including this digit is all spaces, comma becomes space.
				allSpace := true
				for k := 0; k <= i; k++ {
					if !suppressed[k] {
						allSpace = false
						break
					}
				}
				// also if the next digit region still all spaces? Actually comma should still be space if leading zeros suppressed across it.
				// Use allSpace check
				if allSpace {
					sb.WriteByte(' ')
				} else {
					sb.WriteByte(',')
				}
			}
		}
	}
	if scale > 0 {
		sb.WriteByte('.')
		// fractional digits with leading zeros
		fracStr := fmt.Sprintf("%0*d", scale, fracInt)
		sb.WriteString(fracStr)
	}
	return sb.String()
}

func main() {
	// Open ledger file
	var err error
	ledgerFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer ledgerFile.Close()
	reader = bufio.NewReader(ledgerFile)

	MAINPARA()

}

func MAINPARA() {
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if !isFirstRecord() {
		ACCTBREAKPARA()
		BRANCHBREAKPARA()
	}
	ledgerFile.Close()
	GRANDPARA()
}

func READPARA() {
	line, err := reader.ReadString('\n')
	if err != nil {
		// EOF
		WsEofFlag = "Y"
		return
	}
	// strip trailing newline \n and \r
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces to 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	curRec.BrBranch = line[0:2]
	curRec.BrAcct = line[2:6]
	curRec.BrType = line[6:7]
	amtStr := line[7:14]
	// parse 7 digits implied V99
	// remove spaces? Should be digits, but trim
	amtStr = strings.TrimSpace(amtStr)
	if amtStr == "" {
		amtStr = "0"
	}
	// parse integer
	var n int64
	fmt.Sscanf(amtStr, "%d", &n)
	curRec.BrAmt = decimal.New(n, -2)
}

func PROCESSPARA() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			ACCTBREAKPARA()
			BRANCHBREAKPARA()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				ACCTBREAKPARA()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	POSTPARA()
	READPARA()
}

func POSTPARA() {
	WsAmtEd = formatEdited(curRec.BrAmt, 5, []int{3}, 2, false)
	switch curRec.BrType {
	case "D":
		WsBal = WsBal.Add(curRec.BrAmt)
		fmt.Printf("%s D %s\n", curRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(curRec.BrAmt)
		fmt.Printf("%s C %s\n", curRec.BrAcct, WsAmtEd)
	default:
		WsSkipped++
		fmt.Printf("%s ? SKIPPED\n", curRec.BrAcct)
	}
}

func ACCTBREAKPARA() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.NewFromInt(0)
}

func BRANCHBREAKPARA() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.NewFromInt(0)
}

func GRANDPARA() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	// WS-SKIPPED PIC 99 prints zero-padded? But DISPLAY "SKIPPED: " WS-SKIPPED
	// Unedited numeric display: zero padded? Rule says PIC 9(n) zero-padded.
	// However spec shows PIC 99 len2 -> print "05" etc.
	// For COBOL DISPLAY of PIC 99, it prints as integer without leading spaces? But task says unedited numeric prints zero-padded.
	fmt.Printf("SKIPPED: %02d\n", WsSkipped)
}

